    power = inputs['power']
    mod = inputs['modulus']

    # Matrix multiplication with modulo
    def matrix_mult(A, B, mod):
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                for k in range(size):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
        return C

    # Matrix exponentiation using binary exponentiation
    def matrix_pow(M, p, mod):
        size = len(M)
        # Identity matrix
        result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        base = [row[:] for row in M]  # Copy M

        while p > 0:
            if p % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            p //= 2

        return result

    result_matrix = matrix_pow(M, power, mod)

    # Sum all entries
